WITH base AS (SELECT * FROM orders WHERE store_id IN (2, 25, 31, 32) AND order_date > '2024-10-01'), order_month_summary AS (SELECT DATE_TRUNC('MONTH', order_date) AS order_month, customer_id, MIN(discount) AS min_discount, SUM(CASE WHEN status = 'RETURNED' THEN 1 ELSE 0 END) AS returned_count FROM base GROUP BY DATE_TRUNC('MONTH', order_date), customer_id) SELECT * FROM order_month_summary ORDER BY returned_count DESC, customer_id DESC;
